import collections

def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    graph = collections.defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = [0]*(N+1)
    res = 0
    def dfs(node):
        visited[node] = 1
        for child in graph[node]:
            if not visited[child]:
                dfs(child)
    for i in range(1, N+1):
        if not visited[i]:
            res += 1
            dfs(i)
    return res
```

